function validate([queries]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 10000) return 'queries needs 1 to 10^4 pairs.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [n, k].';
    const [n, k] = query;
    if (!Number.isInteger(n) || n < 1 || n > 10000) return 'Each n is an integer from 1 to 10^4.';
    if (!Number.isInteger(k) || k < 1 || k > 10000) return 'Each k is an integer from 1 to 10^4.';
  }
  return null;
}

