function waysToFillArray(queries) {
  const MOD = 1000000007n;
  const choose = (total, pick) => {
    let result = 1n;
    for (let j = 1; j <= pick; j++) {
      result = result * BigInt(total - pick + j) / BigInt(j);
    }
    return result % MOD;
  };
  const answer = [];
  for (const [n, k] of queries) {
    let ways = 1n;
    let rest = k;
    for (let factor = 2; factor * factor <= rest; factor++) {
      let count = 0;
      while (rest % factor === 0) {
        rest /= factor;
        count++;
      }
      ways = ways * choose(n - 1 + count, count) % MOD;
    }
    if (rest > 1) {
      ways = ways * BigInt(n) % MOD;
    }
    answer.push(Number(ways));
  }
  return answer;
}

