function waysToFillArray(queries) {
  // Fill the array one position at a time, tracking how many prefixes reach each divisor of k.
  const MOD = 1000000007;
  return queries.map(([n, k]) => {
    const divisors = [];
    for (let d = 1; d <= k; d++) if (k % d === 0) divisors.push(d);
    let counts = new Map(divisors.map(d => [d, d === 1 ? 1 : 0]));
    for (let position = 0; position < n; position++) {
      const next = new Map(divisors.map(d => [d, 0]));
      for (const [product, count] of counts) {
        if (count === 0) continue;
        for (const d of divisors) {
          const value = product * d;
          if (value <= k && k % value === 0) next.set(value, (next.get(value) + count) % MOD);
        }
      }
      counts = next;
    }
    return counts.get(k);
  });
}

