function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const q = pick(1500, 2000);
    return [Array.from({ length: q }, () => [pick(1, 10000), pick(1, 10000)])];
  }
  const q = pick(1, 5);
  const smooth = [1, 2, 4, 6, 8, 12, 16, 24, 30, 36, 48, 60, 64, 72, 96, 210, 256, 360, 1024, 9973];
  return [Array.from({ length: q }, () => {
    const n = rand() < 0.15 ? 1 : pick(1, 8);
    const k = rand() < 0.5 ? smooth[pick(0, smooth.length - 1)] : pick(1, 120);
    return [n, k];
  })];
}
